import os
from openpyxl import load_workbook
out = os.environ['OUT_XLSX']
wb = load_workbook(out)
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, str) and '"' in c.value:
                c.value = c.value.replace('"','')
wb.save(out)
print('done')
